const ns = 'http://www.w3.org/2000/svg'
const svg = document.createElementNS(ns, 'svg')
svg.setAttribute('width', '100%')
svg.setAttribute('height', '100%')

const path = document.createElementNS(ns, 'path')
path.setAttribute('stroke', 'black')
path.setAttribute('stroke-width', '1.5')
path.setAttribute('stroke-linecap', 'round')
svg.appendChild(path)

document.body.appendChild(svg)
document.body.setAttribute('style', 'display: flex; align-items: stretch; justify-content: stretch; height: 100%')

function setup() {
	const cnv = createCanvas(300, 200, WEBGL)
	pixelDensity(1)
	svg.setAttribute('viewBox', `0 0 ${width} ${height}`)
	cnv.hide()

	background(255)
	push()
	const s = min(width/600, height/600)
	scale(s)
	noStroke()

	push()
	translate(-100, 200, -100)
	rotateX(PI/2)
	fill(50)
	ellipse(0, 0, 650, 400, 50)
	filter(BLUR, s * 40)
	ellipse(0, 0, 500, 400, 50)
	filter(BLUR, s * 20)
	ellipse(0, 0, 400, 400, 50)
	filter(BLUR, s * 10)
	pop()

	push()
	ambientLight(60)
	directionalLight(235, 235, 235, -1, 1, -0.4)
	specularMaterial(255)
	shininess(150)
	sphere(200, 40, 40)
	pop()

	pop()

	const stipple = baseFilterShader().modify(() => {
		getColor((inputs, canvasContent) => {
			const dotSize = 10
			const pos = inputs.texCoord * inputs.canvasSize
			const brightness = pow(getTexture(canvasContent, inputs.texCoord).r, 2)
			const maxR = (1 - brightness) * dotSize / 2
			let color = [1, 1, 1, 1]
			if (brightness < 0.1 + 0.6 * (noise(pos) + 0.5)) {
				color = [0, 0, 0, 1]
			}
			return color
		})
	})
	filter(stipple)

	loadPixels()

	let d = ''
	for (let x = 0; x < width; x++) {
		for (let y = 0; y < height; y++) {
			const b = pixels[(y * width + x) * 4]
			if (b === 0) {
				const offX = random(0.5)
				const offY = random(0.5)
				d += `M${x+offX},${y+offY} L${x+offX+0.01},${y+offY} `
			}
		}
	}
	path.setAttribute('d', d)
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
